static int photo_thai_text(int font, int x, int y, int width, const char * text)
{
    if (!text) return 0;
    for (unsigned i=0; i<sizeof(photo_thai_labels)/sizeof(photo_thai_labels[0]); i++)
    {
        const struct photo_thai_label * t=&photo_thai_labels[i];
        if (strcmp(text,t->key)) continue;
        int w=t->width < width ? t->width : width;
        int h=30*w/t->width;
        if (y+h>480) h=480-y;
        bmp_fill(FONT_BG(font),x,y,w,h);
        for (int row=0; row<h; row++)
            for (int col=0; col<w; col++)
            {
                int bit=(row*36/h)*t->width+col*t->width/w;
                if (t->bits[bit/8] & (1<<(bit%8))) bmp_fill(FONT_FG(font),x+col,y+row,1,1);
            }
        return 1;
    }
    return 0;
}
